   353	                SStream_concat(O, "(%"PRIu64, Length);
   354	
   355	        if (Base)
   356	                SStream_concat(O, ", %%%s", getRegisterName(Base));
   357	        SStream_concat0(O, ")");
   358	
   359	        if (MI->csh->detail) {
